def transform(grid):
    """Replace zeroes at translated copies of the 8-marker shape."""
    h, w = len(grid), len(grid[0])
    marker = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not marker:
        return [row[:] for row in grid]
    r0 = min(r for r, c in marker)
    c0 = min(c for r, c in marker)
    shape = [(r-r0, c-c0) for r, c in marker]
    mh = max(r for r, c in shape) + 1
    mw = max(c for r, c in shape) + 1
    out = [row[:] for row in grid]
    for r in range(h-mh+1):
        for c in range(w-mw+1):
            cells = [(r+dr, c+dc) for dr, dc in shape]
            if all(grid[y][x] == 0 for y, x in cells):
                for y, x in cells:
                    out[y][x] = 8
    return out
